@@ -40,4 +40,36 @@ var _ = Describe("HashFunc", func() {
 		Expect(sum).To(Equal(hashFunc("1", input)))
 		Expect(sum2).To(Equal(hashFunc("2", input)))
 	})
+
+	It("restores a prior hash after setting the same seed", func() {
+		h := hasher.NewHasher()
+		hashFunc := h.HashFunc()
+		h.SetSeed("user", "first")
+		original := hashFunc("user", input)
+		Expect(hashFunc("user", input)).To(Equal(original))
+
+		h.SetSeed("user", "second")
+		Expect(hashFunc("user", input)).NotTo(Equal(original))
+
+		h.SetSeed("user", "first")
+		Expect(hashFunc("user", input)).To(Equal(original))
+		Expect(hashFunc("other", input)).NotTo(Equal(original))
+	})
+
+	It("uses the same explicit seed across hasher instances", func() {
+		first, second := hasher.NewHasher(), hasher.NewHasher()
+		first.SetSeed("user", "saved seed")
+		second.SetSeed("user", "saved seed")
+		Expect(first.HashFunc()("user", input)).To(Equal(second.HashFunc()("user", input)))
+	})
+
+	It("reseeds and restores the global hasher", func() {
+		hasher.SetSeed("saved-user", "saved seed")
+		hashFunc := hasher.HashFunc()
+		original := hashFunc("saved-user", input)
+		hasher.Reseed("saved-user")
+		Expect(hashFunc("saved-user", input)).NotTo(Equal(original))
+		hasher.SetSeed("saved-user", "saved seed")
+		Expect(hashFunc("saved-user", input)).To(Equal(original))
+	})
 })

